import * as BunnySDK from 'https://esm.sh/@bunny.net/edgescript-sdk@0.13.0'

const RUNTIME_PATH = '/.well-known/web-tiles/'

const RUNTIME_HEADERS: Record<string, string> = __RUNTIME_HEADERS__

const DEAD_HEADERS: Record<string, string> = __DEAD_HEADERS__

const FILES: Record<string, {type: string; etag: string; body: string}> =
  __FILES__

const HOST_PATH = '/host/'

const HOST_HEADERS: Record<string, string> = __HOST_HEADERS__

const HOST_FILES: Record<string, {type: string; etag: string; body: string}> =
  __HOST_FILES__

const ALPHABET = 'abcdefghijklmnopqrstuvwxyz'

function baseHost(): string {
  return (Deno.env.get('BASE_HOST') || 't.mu.social')
    .toLowerCase()
    .replace(/^\./, '')
}

/** Twenty random letters, unbiased: a label no one can guess or reuse. */
function randomLabel(): string {
  let out = ''
  while (out.length < 20) {
    for (const byte of crypto.getRandomValues(new Uint8Array(32))) {
      // 234 = 9 * 26: drop the bytes that would favour the first letters.
      if (byte < 234 && out.length < 20) out += ALPHABET[byte % 26]
    }
  }
  return out
}

/**
 * The host the visitor asked for. At the edge the request URL can carry an
 * internal host, so the forwarding headers are tried first; whichever
 * candidate belongs to the base host wins.
 */
function requestHost(req: Request, base: string): string {
  const candidates = [
    req.headers.get('x-forwarded-host'),
    req.headers.get('host'),
    new URL(req.url).host,
  ]
  for (const candidate of candidates) {
    const host = (candidate || '').split(',')[0].trim().toLowerCase()
    const name = host.replace(/:\d+$/, '')
    if (name === base || name.endsWith(`.${base}`)) return host
  }
  return (candidates.find(Boolean) || '').toLowerCase()
}

function dead(
  status: number,
  text: string,
  extra: Record<string, string> = {},
) {
  return new Response(text, {
    status,
    headers: {
      ...DEAD_HEADERS,
      'content-type': 'text/plain; charset=utf-8',
      'cache-control': 'no-store',
      ...extra,
    },
  })
}

/**
 * Expires every cookie the request carried, host-only and for the base host:
 * whatever a tile managed to leave behind under our own names goes. Nothing
 * above the base host is touched.
 */
function scrubCookies(req: Request, res: Response, base: string): Response {
  const names = (req.headers.get('cookie') || '')
    .split(';')
    .map(pair => pair.split('=')[0].trim())
    .filter(name => /^[\w!#$%&'*+.^`|~-]+$/.test(name))
    .slice(0, 50)
  if (!names.length) return res
  const headers = new Headers(res.headers)
  // Says the scrub ran, for when a CDN setting strips the Set-Cookie lines.
  headers.set('x-tile-cookies-expired', String(new Set(names).size))
  const domain = base.replace(/:\d+$/, '')
  for (const name of new Set(names)) {
    const gone = `${name}=; Path=/; Max-Age=0; Expires=Thu, 01 Jan 1970 00:00:00 GMT`
    headers.append('set-cookie', gone)
    headers.append('set-cookie', `${gone}; Domain=${domain}`)
  }
  return new Response(res.body, {status: res.status, headers})
}

BunnySDK.net.http.serve((req: Request): Response => {
  return scrubCookies(req, respond(req), baseHost())
})

function respond(req: Request): Response {
  const base = baseHost()
  const url = new URL(req.url)
  const host = requestHost(req, base)
  const name = host.replace(/:\d+$/, '')
  const port = host.match(/:(\d+)$/)?.[1]

  if (name === `load.${base}`) {
    const origin = `${randomLabel()}.${base}${port ? `:${port}` : ''}`
    // Always https, except for a local run on *.localhost.
    const scheme = base.endsWith('localhost') ? 'http' : 'https'
    return new Response(null, {
      status: 303,
      headers: {
        location: `${scheme}://${origin}${url.pathname}${url.search}`,
        'cache-control': 'no-store',
        'referrer-policy': 'no-referrer',
        'x-content-type-options': 'nosniff',
      },
    })
  }

  // The base host itself: the page native WebViews run a tile in.
  if (name === base) {
    if (url.pathname === HOST_PATH.slice(0, -1)) {
      return new Response(null, {
        status: 308,
        headers: {location: `${HOST_PATH}${url.search}`},
      })
    }
    const file = url.pathname.startsWith(HOST_PATH)
      ? HOST_FILES[url.pathname.slice(HOST_PATH.length) || 'index.html']
      : undefined
    if (!file) return dead(404, 'Nothing here.')
    if (req.method !== 'GET' && req.method !== 'HEAD') {
      return dead(405, 'Method not allowed.', {allow: 'GET, HEAD'})
    }
    return new Response(req.method === 'HEAD' ? null : file.body, {
      status: 200,
      headers: {
        ...HOST_HEADERS,
        // Tiles come from this server's origins only (any port, for local runs).
        'content-security-policy': HOST_HEADERS[
          'content-security-policy'
        ].replace('__FRAME_SRC__', `https://*.${base} http://*.${base}`),
        'content-type': file.type,
        etag: file.etag,
        'cache-control': 'no-cache',
      },
    })
  }

  // Only names this server mints are tile origins.
  const label = name.endsWith(`.${base}`)
    ? name.slice(0, -(base.length + 1))
    : ''
  if (!/^[a-z]{20}$/.test(label)) return dead(404, 'Not a tile origin.')

  if (url.pathname.startsWith(RUNTIME_PATH)) {
    if (req.method !== 'GET' && req.method !== 'HEAD') {
      return dead(405, 'Method not allowed.', {allow: 'GET, HEAD'})
    }
    const file = FILES[url.pathname.slice(RUNTIME_PATH.length) || 'index.html']
    if (file) {
      const headers = {
        ...RUNTIME_HEADERS,
        'content-type': file.type,
        etag: file.etag,
        // The runtime is small and must track releases: revalidate each time.
        'cache-control': 'no-cache',
      }
      if (req.headers.get('if-none-match') === file.etag) {
        return new Response(null, {status: 304, headers})
      }
      return new Response(req.method === 'HEAD' ? null : file.body, {
        status: 200,
        headers,
      })
    }
  }
  return dead(404, 'Not a tile resource.')
}
